"""Render the docs/roadmap.md milestone table from GitHub milestones."""

import argparse
import contextlib
import difflib
import io
import json
import re
import subprocess  # nosec B404 -- runs only git and gh with fixed argument lists, never a shell
import sys
import tempfile
from pathlib import Path

BEGIN_MARKER = (
    "<!-- roadmap:begin (generated by tools/ci/roadmap_render.py --write;"
    " do not edit) -->"
)
END_MARKER = "<!-- roadmap:end -->"
DEFAULT_DOC = Path("docs/roadmap.md")
GH_TIMEOUT_SECONDS = 60


HEADER_LINE = "| Milestone | Scope | Open issues |"
SEPARATOR_LINE = "| :--- | :--- | ---: |"
ROW_PATTERN = re.compile(
    r"^\| \[([^\]]+)\]\((https://github\.com/[^/\s]+/[^/\s]+/milestone/\d+)\) \| (.+) \| (\d+) \|$"
)


class RenderError(Exception):
    """Execution error in roadmap renderer."""


def parse_github_remote(url: str) -> str:
    """Parse owner/name from a GitHub remote URL (https or ssh)."""
    cleaned = url.strip()
    match = re.match(
        r"^(?:https?://github\.com/|git@github\.com:|ssh://git@github\.com/)"
        r"([^/]+/[^/]+?)(?:\.git)?$",
        cleaned,
    )
    if not match:
        raise RenderError(f"unsupported git remote URL: {url}")
    return match.group(1)


def get_repo(repo_override: str | None, git_cwd: Path | None = None) -> str:
    """Resolve repository owner/name from override or git remote."""
    if repo_override:
        cleaned = repo_override.strip()
        if not re.match(r"^[^/]+/[^/]+$", cleaned):
            raise RenderError(
                f"invalid repo format, expected owner/name: {repo_override}"
            )
        return cleaned
    try:
        result = subprocess.run(  # nosec B603 -- fixed git argv list, no shell
            ["git", "remote", "get-url", "origin"],
            cwd=git_cwd,
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as error:
        raise RenderError(f"failed to run git remote get-url: {error}") from error
    if result.returncode != 0:
        detail = result.stderr.strip() or f"exit {result.returncode}"
        raise RenderError(f"git remote get-url origin failed: {detail}")
    return parse_github_remote(result.stdout)


def fetch_milestones_from_gh(repo: str) -> str:
    """Fetch open milestones JSON from GitHub CLI via gh api."""
    endpoint = f"repos/{repo}/milestones?state=open&per_page=100"
    try:
        result = subprocess.run(  # nosec B603 -- fixed gh argv list, no shell; repo validated as owner/name
            ["gh", "api", endpoint],
            capture_output=True,
            text=True,
            timeout=GH_TIMEOUT_SECONDS,
            check=False,
        )
    except FileNotFoundError as error:
        raise RenderError(f"gh command not found: {error}") from error
    except subprocess.TimeoutExpired as error:
        raise RenderError(
            f"gh api timed out after {GH_TIMEOUT_SECONDS} seconds"
        ) from error
    except OSError as error:
        raise RenderError(f"gh api failed to execute: {error}") from error
    if result.returncode != 0:
        detail = result.stderr.strip() or f"exit {result.returncode}"
        raise RenderError(f"gh api {endpoint} failed: {detail}")
    return result.stdout


def load_milestones(
    repo: str, milestones_json: Path | None = None
) -> list[dict]:
    """Load and validate milestone list from a file or GitHub API."""
    if milestones_json is not None:
        try:
            raw = milestones_json.read_text(encoding="utf-8")
        except OSError as error:
            raise RenderError(
                f"cannot read milestones file {milestones_json}: {error}"
            ) from error
    else:
        raw = fetch_milestones_from_gh(repo)
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as error:
        raise RenderError(f"invalid JSON: {error}") from error
    if not isinstance(data, list):
        raise RenderError("milestones JSON is not a list")
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            raise RenderError(f"milestone entry {idx} is not an object")
        for key in ("title", "html_url", "open_issues"):
            if key not in item:
                raise RenderError(
                    f"milestone entry {idx} missing required field: {key}"
                )
    return data


def parse_sort_key(item: dict) -> tuple[int, tuple[int, ...], int, str]:
    """Parse sort key: dotted ints first, non-version titles after by number."""
    title = str(item.get("title", "")).strip()
    parts = title.split(".")
    if parts and all(p.isdigit() for p in parts):
        version_tuple = tuple(int(p) for p in parts)
        return (0, version_tuple, 0, title)
    raw_num = item.get("number", 0)
    number = raw_num if isinstance(raw_num, int) else 0
    return (1, (), number, title)


def escape_cell(text: str) -> str:
    """Escape a table cell: backslashes first, then pipes, so check_shape reads every pipe as escaped."""
    return text.replace("\\", "\\\\").replace("|", r"\|")


def format_description(desc_raw: object) -> str:
    """Format scope description: collapse whitespace, escape pipe, default on empty."""
    if desc_raw is None:
        return "No description."
    text = str(desc_raw)
    collapsed = " ".join(text.split())
    escaped = escape_cell(collapsed)
    if not escaped:
        return "No description."
    return escaped


def render_table(milestones: list[dict]) -> str:
    """Render milestone items into a Markdown table block."""
    sorted_ms = sorted(milestones, key=parse_sort_key)
    lines = [
        "| Milestone | Scope | Open issues |",
        "| :--- | :--- | ---: |",
    ]
    for item in sorted_ms:
        title = escape_cell(str(item["title"]).strip())
        html_url = str(item["html_url"]).strip()
        desc = format_description(item.get("description"))
        open_issues = item["open_issues"]
        lines.append(f"| [{title}]({html_url}) | {desc} | {open_issues} |")
    return "\n".join(lines)


def locate_block(content: str) -> tuple[int, int]:
    """Find start and end offsets of block content between markers."""
    begin_count = content.count(BEGIN_MARKER)
    if begin_count == 0:
        raise RenderError("begin marker missing")
    if begin_count > 1:
        raise RenderError("duplicate begin marker")

    end_count = content.count(END_MARKER)
    if end_count == 0:
        raise RenderError("end marker missing")
    if end_count > 1:
        raise RenderError("duplicate end marker")

    begin_idx = content.find(BEGIN_MARKER)
    end_idx = content.find(END_MARKER)
    if begin_idx >= end_idx:
        raise RenderError("markers out of order")

    after_begin = begin_idx + len(BEGIN_MARKER)
    if content[after_begin:after_begin + 2] == "\r\n":
        block_start = after_begin + 2
    elif content[after_begin:after_begin + 1] == "\n":
        block_start = after_begin + 1
    else:
        block_start = after_begin

    return block_start, end_idx


def write_roadmap(doc_path: Path, table_text: str) -> None:
    """Rewrite only the block between markers in doc_path."""
    try:
        content = doc_path.read_text(encoding="utf-8")
    except OSError as error:
        raise RenderError(f"cannot read {doc_path}: {error}") from error
    start, end = locate_block(content)
    newline = "\r\n" if "\r\n" in content else "\n"
    expected_block = table_text + newline
    new_content = content[:start] + expected_block + content[end:]
    try:
        doc_path.write_text(new_content, encoding="utf-8")
    except OSError as error:
        raise RenderError(f"cannot write {doc_path}: {error}") from error


def check_roadmap(doc_path: Path, table_text: str) -> int:
    """Verify doc_path has expected table between markers; print diff if stale."""
    try:
        content = doc_path.read_text(encoding="utf-8")
    except OSError as error:
        raise RenderError(f"cannot read {doc_path}: {error}") from error
    start, end = locate_block(content)
    current_block = content[start:end]
    newline = "\r\n" if "\r\n" in content else "\n"
    expected_block = table_text + newline
    if current_block != expected_block:
        doc_str = str(doc_path)
        print(
            f"roadmap_render: {doc_str} is stale; "
            "run python3 tools/ci/roadmap_render.py --write"
        )
        diff = difflib.unified_diff(
            current_block.splitlines(keepends=True),
            expected_block.splitlines(keepends=True),
            fromfile=f"{doc_str} (current)",
            tofile=f"{doc_str} (rendered)",
        )
        sys.stdout.writelines(diff)
        return 1
    return 0


def has_unescaped_pipe(text: str) -> bool:
    """Return True if text contains a pipe character not escaped with backslash."""
    idx = 0
    while idx < len(text):
        if text[idx] == "|":
            bs_count = 0
            back_idx = idx - 1
            while back_idx >= 0 and text[back_idx] == "\\":
                bs_count += 1
                back_idx -= 1
            if bs_count % 2 == 0:
                return True
        idx += 1
    return False


def check_block_ending(block: str, line_count: int) -> tuple[int, str] | None:
    """Verify block ends with exactly one newline before END_MARKER."""
    if not block.endswith(("\n", "\r\n")):
        return (
            max(1, line_count),
            "block does not end with a newline before END_MARKER",
        )
    trimmed = block[:-2] if block.endswith("\r\n") else block[:-1]
    if trimmed.endswith(("\n", "\r")):
        return (
            max(1, line_count),
            "block ends with multiple newlines before END_MARKER",
        )
    return None


def validate_headers(lines: list[str]) -> list[tuple[int, str]]:
    """Validate table header and separator lines."""
    findings: list[tuple[int, str]] = []
    if not lines or lines[0] != HEADER_LINE:
        findings.append((1, f"unexpected header, expected '{HEADER_LINE}'"))
    if len(lines) < 2 or lines[1] != SEPARATOR_LINE:
        findings.append((2, f"unexpected separator, expected '{SEPARATOR_LINE}'"))
    return findings


def validate_row_content(
    line: str, line_num: int, seen_titles: set[str], seen_urls: set[str]
) -> tuple[tuple[int, str] | None, dict | None]:
    """Validate data row format, scope cell, duplicates, and return milestone dict."""
    match = ROW_PATTERN.match(line)
    if not match:
        return (line_num, "invalid data row format"), None
    title, url, scope, _ = match.groups()
    if has_unescaped_pipe(title):
        return (line_num, "milestone title contains unescaped pipe"), None
    if not scope.strip():
        return (line_num, "scope cell must not be empty"), None
    if has_unescaped_pipe(scope):
        return (line_num, "scope cell contains unescaped pipe"), None
    if title in seen_titles:
        return (line_num, f"duplicate milestone title: {title!r}"), None
    if url in seen_urls:
        return (line_num, f"duplicate milestone URL: {url!r}"), None
    seen_titles.add(title)
    seen_urls.add(url)
    number = int(url.rsplit("/", 1)[-1])
    return None, {"title": title, "number": number}


def validate_data_rows(lines: list[str]) -> list[tuple[int, str]]:
    """Validate data rows format, uniqueness, and ordering."""
    if len(lines) < 3:
        return [(max(1, len(lines) + 1), "expected at least one milestone data row")]

    findings: list[tuple[int, str]] = []
    seen_titles: set[str] = set()
    seen_urls: set[str] = set()
    max_key: tuple[int, tuple[int, ...], int, str] | None = None

    for idx, line in enumerate(lines[2:], start=3):
        err, item = validate_row_content(line, idx, seen_titles, seen_urls)
        if err is not None:
            findings.append(err)
            continue
        key = parse_sort_key(item)
        if max_key is not None and key < max_key:
            findings.append((idx, f"row out of order: {item['title']!r}"))
            continue
        max_key = key
    return findings


def check_shape(doc_path: Path) -> int:
    """Verify roadmap block conforms to shape rules without network access."""
    doc = Path(doc_path)
    try:
        content = doc.read_text(encoding="utf-8")
    except OSError as error:
        raise RenderError(f"cannot read {doc}: {error}") from error

    start, end = locate_block(content)
    block = content[start:end]
    lines = block.splitlines()

    findings: list[tuple[int, str]] = []
    ending_err = check_block_ending(block, len(lines))
    if ending_err is not None:
        findings.append(ending_err)

    data_lines = lines
    while data_lines and data_lines[-1] == "":
        data_lines = data_lines[:-1]

    findings.extend(validate_headers(data_lines))
    findings.extend(validate_data_rows(data_lines))

    if not findings:
        return 0

    doc_str = str(doc)
    findings.sort(key=lambda item: item[0])
    for line_num, reason in findings:
        print(f"roadmap_render: {doc_str}: {reason} (line {line_num} of block)")
    return 1


def test_case_render_and_stale(tmp_path: Path) -> list[tuple[str, bool]]:
    """Test render then check green, planted stale count, and planted extra row."""
    doc = tmp_path / "roadmap.md"
    template = f"# Roadmap\n{BEGIN_MARKER}\n{END_MARKER}\n## Watch-aware\n"
    doc.write_text(template, encoding="utf-8")

    data = [
        {
            "title": "0.9",
            "html_url": "https://example.com/14",
            "description": "Desc 0.9",
            "open_issues": 87,
        },
        {
            "title": "0.10",
            "html_url": "https://example.com/15",
            "description": "Desc 0.10",
            "open_issues": 29,
        },
    ]
    table = render_table(data)
    write_roadmap(doc, table)
    rc_check = check_roadmap(doc, table)
    ok_green = rc_check == 0

    doc_content = doc.read_text(encoding="utf-8")
    stale_content = doc_content.replace("| 87 |", "| 26 |")
    doc.write_text(stale_content, encoding="utf-8")
    with contextlib.redirect_stdout(io.StringIO()):
        rc_stale = check_roadmap(doc, table)
    ok_stale = rc_stale == 1

    extra_row = "| [0.8](https://example.com/13) | Extra | 0 |\n"
    start, _ = locate_block(stale_content)
    extra_content = stale_content[:start] + extra_row + stale_content[start:]
    doc.write_text(extra_content, encoding="utf-8")
    with contextlib.redirect_stdout(io.StringIO()):
        rc_extra = check_roadmap(doc, table)
    ok_extra = rc_extra == 1

    return [
        ("render then check green", ok_green),
        ("planted stale count (doc says 26, data 87) -> 1", ok_stale),
        ("planted extra row -> 1", ok_extra),
    ]


def test_case_errors_and_formatting(tmp_path: Path) -> list[tuple[str, bool]]:
    """Test markers missing, non-list JSON, and description pipe escaping."""
    doc_bad = tmp_path / "bad.md"
    doc_bad.write_text("# No markers here\n", encoding="utf-8")
    ok_missing = False
    try:
        locate_block(doc_bad.read_text(encoding="utf-8"))
    except RenderError:
        ok_missing = True

    dup_text = f"{BEGIN_MARKER}\n{BEGIN_MARKER}\n{END_MARKER}\n"
    ok_dup = False
    try:
        locate_block(dup_text)
    except RenderError:
        ok_dup = True

    rev_text = f"{END_MARKER}\n{BEGIN_MARKER}\n"
    ok_rev = False
    try:
        locate_block(rev_text)
    except RenderError:
        ok_rev = True

    json_bad = tmp_path / "bad.json"
    json_bad.write_text('{"error": "not a list"}', encoding="utf-8")
    ok_json_list = False
    try:
        load_milestones("owner/repo", milestones_json=json_bad)
    except RenderError:
        ok_json_list = True

    json_entry_bad = tmp_path / "bad_entry.json"
    json_entry_bad.write_text('[{"title": "0.9"}]', encoding="utf-8")
    ok_entry = False
    try:
        load_milestones("owner/repo", milestones_json=json_entry_bad)
    except RenderError:
        ok_entry = True

    pipe_data = [
        {
            "title": "0.9",
            "html_url": "https://example.com/14",
            "description": "Item A | Item B",
            "open_issues": 1,
        }
    ]
    rendered_pipe = render_table(pipe_data)
    ok_pipe = r"Item A \| Item B" in rendered_pipe

    return [
        ("markers missing -> 2", ok_missing and ok_dup and ok_rev),
        ("non-list JSON -> 2", ok_json_list and ok_entry),
        ("pipe in description escaped", ok_pipe),
    ]


def test_case_order_and_outside(tmp_path: Path) -> list[tuple[str, bool]]:
    """Test version ordering (0.9 before 0.10) and text outside block preservation."""
    order_data = [
        {
            "title": "0.10",
            "html_url": "https://example.com/10",
            "open_issues": 10,
        },
        {"title": "0.9", "html_url": "https://example.com/9", "open_issues": 9},
        {
            "title": "Backlog",
            "html_url": "https://example.com/b",
            "number": 1,
            "open_issues": 0,
        },
    ]
    rendered = render_table(order_data)
    pos_9 = rendered.find("[0.9]")
    pos_10 = rendered.find("[0.10]")
    pos_backlog = rendered.find("[Backlog]")
    ok_order = 0 <= pos_9 < pos_10 < pos_backlog

    doc_test = tmp_path / "preserve.md"
    prefix = "# Roadmap\nIntro line.\n"
    suffix = "\n## Watch-aware modes\nPreserve this text verbatim.\n"
    doc_test.write_text(
        f"{prefix}{BEGIN_MARKER}\nOld\n{END_MARKER}{suffix}", encoding="utf-8"
    )
    write_roadmap(doc_test, rendered)
    res_text = doc_test.read_text(encoding="utf-8")
    ok_outside = res_text.startswith(
        f"{prefix}{BEGIN_MARKER}\n"
    ) and res_text.endswith(f"\n{END_MARKER}{suffix}")

    return [
        ("version order 0.9 before 0.10", ok_order),
        ("text outside block untouched by --write", ok_outside),
    ]


def check_planted_shape(tmp_path: Path, filename: str, content: str) -> bool:
    """Write content to doc in tmp_path and check that check_shape fails with 1."""
    doc = tmp_path / filename
    doc.write_text(content, encoding="utf-8")
    with contextlib.redirect_stdout(io.StringIO()):
        return check_shape(doc) == 1


def test_case_shape(tmp_path: Path) -> list[tuple[str, bool]]:
    """Test check_shape with valid rendered table and planted invalid cases."""
    data = [
        {"title": "0.9", "html_url": "https://github.com/o/r/milestone/14", "open_issues": 1},
        {"title": "0.10", "html_url": "https://github.com/o/r/milestone/15", "open_issues": 2},
    ]
    doc = tmp_path / "shape.md"
    doc.write_text(f"{BEGIN_MARKER}\n{END_MARKER}\n", encoding="utf-8")
    table = render_table(data)
    write_roadmap(doc, table)
    valid_text = doc.read_text(encoding="utf-8")
    lines = table.splitlines()

    order_table = "\n".join([lines[0], lines[1], lines[3], lines[2]])
    dup_table = "\n".join([lines[0], lines[1], lines[2], lines[2]])
    order_doc = f"{BEGIN_MARKER}\n{order_table}\n{END_MARKER}\n"
    dup_doc = f"{BEGIN_MARKER}\n{dup_table}\n{END_MARKER}\n"
    hdr_text = valid_text.replace(HEADER_LINE, "| Milestone | Scope | Issues |")

    return [
        ("rendered table (from render_table) passes check_shape -> 0", check_shape(doc) == 0),
        ('planted non-numeric count ("| 8x |") -> 1', check_planted_shape(
            tmp_path, "nonnum.md", valid_text.replace("| 1 |", "| 8x |")
        )),
        ("planted out-of-order rows (0.10 before 0.9) -> 1", check_planted_shape(
            tmp_path, "order.md", order_doc
        )),
        ("planted unescaped pipe in scope -> 1", check_planted_shape(
            tmp_path, "pipe.md", valid_text.replace("No description.", "A | B")
        )),
        ("planted duplicate row -> 1", check_planted_shape(
            tmp_path, "dup.md", dup_doc
        )),
        ("planted wrong header -> 1", check_planted_shape(
            tmp_path, "hdr.md", hdr_text
        )),
    ]


def test_case_title_pipe(tmp_path: Path) -> list[tuple[str, bool]]:
    """Test milestone title pipe escaping in render_table and check_shape."""
    data = [
        {
            "title": "Phase 1 | Phase 2",
            "html_url": "https://github.com/o/r/milestone/1",
            "open_issues": 0,
        }
    ]
    table = render_table(data)
    doc = tmp_path / "title_pipe.md"
    doc.write_text(f"{BEGIN_MARKER}\n{table}\n{END_MARKER}\n", encoding="utf-8")
    raw_row = (
        "| [Phase 1 | Phase 2](https://github.com/o/r/milestone/1) "
        "| No description. | 0 |"
    )
    raw_doc = (
        f"{BEGIN_MARKER}\n{HEADER_LINE}\n{SEPARATOR_LINE}\n{raw_row}\n"
        f"{END_MARKER}\n"
    )

    backslash = [
        {
            "title": "A \\| B",
            "html_url": "https://github.com/o/r/milestone/2",
            "description": "C \\| D",
            "open_issues": 1,
        }
    ]
    bs_doc = tmp_path / "title_backslash.md"
    bs_doc.write_text(
        f"{BEGIN_MARKER}\n{render_table(backslash)}\n{END_MARKER}\n", encoding="utf-8"
    )

    return [
        (
            "rendered title and scope holding a backslash before a pipe pass check_shape -> 0",
            check_shape(bs_doc) == 0,
        ),
        (
            'render_table with title "Phase 1 | Phase 2" contains "Phase 1 \\| Phase 2"',
            r"Phase 1 \| Phase 2" in table,
        ),
        (
            "rendered table with that title passes check_shape -> 0",
            check_shape(doc) == 0,
        ),
        (
            'planted row with raw "Phase 1 | Phase 2" title -> check_shape 1',
            check_planted_shape(tmp_path, "raw_title.md", raw_doc),
        ),
    ]


def self_test() -> int:
    """Run internal test suite with planted cases; exit 1 on any failure."""
    with tempfile.TemporaryDirectory() as tmp_str:
        tmp_path = Path(tmp_str)
        cases: list[tuple[str, bool]] = []
        cases.extend(test_case_render_and_stale(tmp_path))
        cases.extend(test_case_errors_and_formatting(tmp_path))
        cases.extend(test_case_order_and_outside(tmp_path))
        cases.extend(test_case_shape(tmp_path))
        cases.extend(test_case_title_pipe(tmp_path))

    failed = False
    for name, ok in cases:
        if ok:
            print(f"ok   {name}")
        else:
            print(f"FAIL {name}")
            failed = True
    return 1 if failed else 0


def main(argv: list[str] | None = None) -> int:
    """Parse CLI arguments, execute selected mode, and return process exit code."""
    parser = argparse.ArgumentParser(
        description="Render docs/roadmap.md milestone table from GitHub."
    )
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument(
        "--write", action="store_true", help="rewrite roadmap block"
    )
    group.add_argument(
        "--check", action="store_true", help="check roadmap block"
    )
    group.add_argument(
        "--check-shape",
        action="store_true",
        help="verify roadmap block conforms to shape rules without network",
    )
    group.add_argument(
        "--self-test", action="store_true", help="run self-test suite"
    )

    parser.add_argument(
        "--repo", default=None, help="GitHub repo owner/name override"
    )
    parser.add_argument(
        "--milestones-json",
        type=Path,
        default=None,
        help="read milestone JSON from file instead of gh api",
    )
    parser.add_argument(
        "--doc",
        type=Path,
        default=DEFAULT_DOC,
        help="path to roadmap markdown document",
    )

    args = parser.parse_args(argv)
    if args.self_test:
        return self_test()

    try:
        if args.check_shape:
            return check_shape(args.doc)
        repo = get_repo(args.repo)
        milestones = load_milestones(repo, args.milestones_json)
        table = render_table(milestones)
        if args.write:
            write_roadmap(args.doc, table)
            return 0
        return check_roadmap(args.doc, table)
    except RenderError as error:
        print(f"roadmap_render: cannot run: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
